def forward(groups):
    total, boot, init, finish = (int(groups[0]), int(groups[1]), int(groups[2]), int(groups[3]))
    return {'stored': [total, boot, init, finish], 'layout': []}

def inverse(record):
    total, boot, init, finish = record['stored']
    return f'total = {total}, boot = {boot}, init = {init}, finish = {finish}'
